 33	
 34	constexpr std::size_t kMaxFibRecords = 200000;
 35	constexpr std::size_t kMaxTraceRecords = 1000000;
 36	constexpr std::size_t kMaxLineBytes = 256;
 37	constexpr std::size_t kMaxRows = 400001;
 38	constexpr std::uint64_t kImageByteCap = 64ull * 1024ull * 1024ull;
