 86	// --------------------------------------------------------------- file input
 87	
 88	// Reads a whole (small) file, refusing anything beyond `cap` bytes.
 89	std::string read_file(const std::string& path, std::uint64_t cap) {
 90	    std::ifstream in(path, std::ios::binary);
 91	    if (!in.is_open()) fail("cannot open input file: " + path);
 92	    in.seekg(0, std::ios::end);
 93	    if (!in.fail()) {
 94	        const std::streamoff sz = in.tellg();
 95	        if (sz >= 0 && static_cast<std::uint64_t>(sz) > cap)
 96	            fail("input file too large: " + path);
 97	        in.clear();
 98	    }
 99	    in.seekg(0, std::ios::beg);
100	    if (in.fail()) fail("cannot read input file: " + path);
101	    std::string data;
102	    char chunk[65536];
103	    for (;;) {
104	        in.read(chunk, sizeof chunk);
105	        const std::streamsize got = in.gcount();
106	        if (got > 0) {
107	            if (data.size() + static_cast<std::size_t>(got) > cap)
108	                fail("input file too large: " + path);
109	            data.append(chunk, static_cast<std::size_t>(got));
110	        }
111	        if (in.eof()) break;
112	        if (in.bad()) fail("error reading input file: " + path);
113	        if (got == 0) break;
114	    }
115	    return data;
116	}
