118	// Streams a text file line by line without holding it in memory.  A final line
119	// without a trailing newline is still a line; overlong lines are rejected.
120	class LineReader {
121	  public:
122	    explicit LineReader(const std::string& path) : in_(path, std::ios::binary) {
123	        if (!in_.is_open()) fail("cannot open input file: " + path);
124	    }
125	
126	    bool next(std::string& line) {
127	        if (done_) return false;
128	        for (;;) {
129	            const std::size_t nl = buf_.find('\n', pos_);
130	            if (nl != std::string::npos) {
131	                if (nl - pos_ > kMaxLineBytes) fail("input line too long");
132	                line.assign(buf_, pos_, nl - pos_);
133	                pos_ = nl + 1;
134	                return true;
135	            }
136	            if (at_eof_) {
137	                done_ = true;
138	                if (pos_ < buf_.size()) {
139	                    if (buf_.size() - pos_ > kMaxLineBytes) fail("input line too long");
140	                    line.assign(buf_, pos_, buf_.size() - pos_);
141	                    pos_ = buf_.size();
142	                    return true;
143	                }
144	                return false;
145	            }
146	            if (buf_.size() - pos_ > kMaxLineBytes) fail("input line too long");
147	            if (pos_ > 0) {
148	                buf_.erase(0, pos_);
149	                pos_ = 0;
150	            }
151	            char chunk[65536];
152	            in_.read(chunk, sizeof chunk);
153	            const std::streamsize got = in_.gcount();
154	            if (got > 0) buf_.append(chunk, static_cast<std::size_t>(got));
155	            if (in_.eof()) at_eof_ = true;
156	            else if (in_.bad()) fail("error reading input file");
157	        }
158	    }
159	
160	  private:
161	    std::ifstream in_;
162	    std::string buf_;
163	    std::size_t pos_ = 0;
164	    bool at_eof_ = false;
165	    bool done_ = false;
166	};
