170	// Validates a full IPv6 address with inet_pton(3) and returns its upper
171	// 64 bits, which is the lookup key for prefixes of length at most 64.
172	std::uint64_t address_key(const char* begin, std::size_t len) {
173	    if (len == 0 || len > kMaxLineBytes) fail("invalid IPv6 address");
174	    char text[kMaxLineBytes + 1];
175	    std::memcpy(text, begin, len);
176	    text[len] = '\0';
177	    in6_addr addr;
178	    if (inet_pton(AF_INET6, text, &addr) != 1) fail("invalid IPv6 address");
179	    std::uint64_t key = 0;
180	    for (int i = 0; i < 8; ++i)
181	        key = (key << 8) | static_cast<std::uint64_t>(addr.s6_addr[i]);
182	    return key;
183	}
