185	// ------------------------------------------------------- decimal field parse
186	
187	// Accepts ASCII decimal digits with leading zeros; the value must fit `maxv`.
188	std::uint64_t parse_unsigned_input(std::string_view s, std::uint64_t maxv,
189	                                   const char* what) {
190	    if (s.empty()) fail(std::string("invalid ") + what);
191	    for (char c : s)
192	        if (c < '0' || c > '9') fail(std::string("invalid ") + what);
193	    std::size_t i = 0;
194	    while (i < s.size() && s[i] == '0') ++i;  // leading zeros are allowed
195	    const std::string_view t = s.substr(i);    // empty means zero
196	    if (t.size() > 10) fail(std::string("invalid ") + what);
197	    std::uint64_t v = 0;
198	    for (char c : t) v = v * 10 + static_cast<std::uint64_t>(c - '0');
199	    if (v > maxv) fail(std::string("invalid ") + what);
200	    return v;
201	}
