203	// ------------------------------------------------------------------ the FIB
204	
205	struct Prefix {
206	    std::uint64_t start;  // normalized network, upper 64 bits, host bits clear
207	    std::uint32_t hop;
208	    std::uint8_t len;
209	};
210	
211	std::vector<Prefix> parse_fib(const std::string& path) {
212	    LineReader in(path);
213	    std::string line;
214	    std::vector<std::string_view> fields;
215	    std::vector<Prefix> prefixes;
216	    while (in.next(line)) {
217	        tokenize(line, fields);
218	        if (fields.empty()) continue;  // blank line
219	        if (fields.size() != 2) fail("malformed FIB record");
220	        const std::string_view spec = fields[0];
221	        const std::size_t slash = spec.find('/');
222	        if (slash == std::string_view::npos) fail("malformed FIB prefix");
223	        const std::uint64_t len =
224	            parse_unsigned_input(spec.substr(slash + 1), 64, "prefix length");
225	        const std::uint64_t key = address_key(spec.data(), slash);
226	        const std::uint64_t hop =
227	            parse_unsigned_input(fields[1], 4294967295ull, "next hop");
228	        const std::uint64_t start =
229	            (len == 0) ? 0 : (key & (~0ull << (64 - len)));
230	        prefixes.push_back(Prefix{start, static_cast<std::uint32_t>(hop),
231	                                 static_cast<std::uint8_t>(len)});
232	        if (prefixes.size() > kMaxFibRecords) fail("too many FIB records");
233	    }
234	    return prefixes;
235	}
