344	// ------------------------------------------------------------ image reading
345	
346	// Canonical image field: "-1" or unpadded decimal within range.
347	std::int64_t parse_image_field(std::string_view s, std::uint64_t maxv,
348	                               const char* what) {
349	    if (s == std::string_view("-1")) return -1;
350	    const std::string prefix = std::string("malformed image ") + what;
351	    if (s.empty()) fail(prefix);
352	    if (s.size() > 10) fail(prefix);
353	    for (char c : s)
354	        if (c < '0' || c > '9') fail(prefix);
355	    if (s.size() > 1 && s[0] == '0') fail(prefix);  // padded spelling
356	    std::uint64_t v = 0;
357	    for (char c : s) v = v * 10 + static_cast<std::uint64_t>(c - '0');
358	    if (v > maxv) fail(prefix);
359	    return static_cast<std::int64_t>(v);
360	}
361	
362	Row parse_image_row(std::string_view s) {
363	    if (s.size() < 20) fail("malformed image row");
364	    std::uint64_t start = 0;
365	    for (std::size_t i = 0; i < 16; ++i) {
366	        const char c = s[i];
367	        std::uint64_t d;
368	        if (c >= '0' && c <= '9') d = static_cast<std::uint64_t>(c - '0');
369	        else if (c >= 'a' && c <= 'f') d = static_cast<std::uint64_t>(c - 'a') + 10;
370	        else fail("malformed image row key");
371	        start = (start << 4) | d;
372	    }
373	    if (s[16] != ' ') fail("malformed image row spacing");
374	    const std::size_t second = s.find(' ', 17);
375	    if (second == std::string_view::npos || second == 17)
376	        fail("malformed image row spacing");
377	    const std::string_view hop_text = s.substr(17, second - 17);
378	    const std::string_view len_text = s.substr(second + 1);
379	    if (len_text.empty() || len_text.find(' ') != std::string_view::npos)
380	        fail("malformed image row spacing");
381	    const std::int64_t hop = parse_image_field(hop_text, 4294967295ull, "next hop");
382	    const std::int64_t len = parse_image_field(len_text, 64, "prefix length");
383	    if ((hop < 0) != (len < 0)) fail("malformed image row pair");
384	    return Row{start,
385	               hop < 0 ? 0u : static_cast<std::uint32_t>(hop),
386	               static_cast<std::int32_t>(len)};
387	}
