389	std::vector<Row> load_image(const std::string& path) {
390	    const std::string data = read_file(path, kImageByteCap);
391	    if (data.empty() || data.back() != '\n')
392	        fail("malformed image: missing final newline");
393	    std::size_t pos = 0;
394	    auto next_line = [&](std::string_view& out) -> bool {
395	        if (pos >= data.size()) return false;
396	        const std::size_t nl = data.find('\n', pos);  // always found
397	        out = std::string_view(data.data() + pos, nl - pos);
398	        pos = nl + 1;
399	        return true;
400	    };
401	
402	    std::string_view line;
403	    if (!next_line(line) || line != std::string_view("PLANB64 1"))
404	        fail("malformed image header");
405	    if (!next_line(line)) fail("malformed image: missing row count");
406	    if (line.empty() || line.size() > 6) fail("malformed image row count");
407	    for (char c : line)
408	        if (c < '0' || c > '9') fail("malformed image row count");
409	    if (line.size() > 1 && line[0] == '0') fail("malformed image row count");
410	    std::uint64_t count = 0;
411	    for (char c : line) count = count * 10 + static_cast<std::uint64_t>(c - '0');
412	    if (count < 1 || count > kMaxRows) fail("malformed image row count");
413	
414	    std::vector<Row> rows;
415	    rows.reserve(static_cast<std::size_t>(count));
416	    for (std::uint64_t i = 0; i < count; ++i) {
417	        if (!next_line(line)) fail("malformed image: fewer rows than declared");
418	        const Row r = parse_image_row(line);
419	        if (i == 0) {
420	            if (r.start != 0) fail("malformed image: first key must be zero");
421	        } else {
422	            const Row& prev = rows.back();
423	            if (r.start <= prev.start) fail("malformed image: keys not strictly increasing");
424	            if (r.hop == prev.hop && r.len == prev.len)
425	                fail("malformed image: equal adjacent pairs");
426	        }
427	        rows.push_back(r);
428	    }
429	    if (next_line(line)) fail("malformed image: extra records");
430	    return rows;
431	}
