433	// ---------------------------------------------------------------- the trace
434	
435	std::vector<std::uint64_t> parse_trace(const std::string& path) {
436	    LineReader in(path);
437	    std::string line;
438	    std::vector<std::string_view> fields;
439	    std::vector<std::uint64_t> keys;
440	    while (in.next(line)) {
441	        tokenize(line, fields);
442	        if (fields.empty()) continue;  // blank line
443	        if (fields.size() != 1) fail("malformed trace record");
444	        keys.push_back(address_key(fields[0].data(), fields[0].size()));
445	        if (keys.size() > kMaxTraceRecords) fail("too many trace records");
446	    }
447	    return keys;
448	}
