450	// ------------------------------------------------------------------ lookups
451	
452	// Answers every query with a predecessor search over the interval rows.
453	// `batch` only controls how many queries are resolved per iteration; the
454	// semantics are identical to the scalar path.
455	void emit_answers(const std::vector<Row>& rows,
456	                  const std::vector<std::uint64_t>& keys, std::size_t batch) {
457	    std::string out;
458	    out.reserve(keys.size() * 6 + 64);
459	    std::size_t i = 0;
460	    while (i < keys.size()) {
461	        const std::size_t n = std::min(batch, keys.size() - i);
462	        for (std::size_t j = 0; j < n; ++j) {
463	            const std::uint64_t key = keys[i + j];
464	            std::size_t lo = 0, hi = rows.size();
465	            while (lo < hi) {  // first row with start > key
466	                const std::size_t mid = lo + (hi - lo) / 2;
467	                if (rows[mid].start <= key) lo = mid + 1;
468	                else hi = mid;
469	            }
470	            const Row& r = rows[lo - 1];  // rows[0].start == 0, so lo >= 1
471	            if (r.len < 0) {
472	                out.append("-1 -1\n", 6);
473	            } else {
474	                append_dec(out, static_cast<std::int64_t>(r.hop));
475	                out.push_back(' ');
476	                append_dec(out, r.len);
477	                out.push_back('\n');
478	            }
479	        }
480	        i += n;
481	    }
482	    if (!out.empty() &&
483	        std::fwrite(out.data(), 1, out.size(), stdout) != out.size())
484	        fail("cannot write output");
485	    if (std::fflush(stdout) != 0) fail("cannot write output");
486	}
