488	std::size_t parse_batch_size(const char* text) {
489	    const std::string_view s(text);
490	    if (s.empty()) fail("invalid batch size");
491	    for (char c : s)
492	        if (c < '0' || c > '9') fail("invalid batch size");
493	    std::size_t i = 0;
494	    while (i < s.size() && s[i] == '0') ++i;  // leading zeros are allowed
495	    const std::string_view t = s.substr(i);
496	    if (t.empty()) fail("invalid batch size");  // value zero
497	    if (t.size() > 3) fail("invalid batch size");  // greater than 256
498	    std::uint64_t v = 0;
499	    for (char c : t) v = v * 10 + static_cast<std::uint64_t>(c - '0');
500	    if (v < 1 || v > 256) fail("invalid batch size");
501	    return static_cast<std::size_t>(v);
502	}
