506	int main(int argc, char** argv) {
507	    try {
508	        if (argc < 2) fail("usage: planb64 build FIB IMAGE | planb64 lookup IMAGE"
509	                           " TRACE scalar | planb64 lookup IMAGE TRACE batch"
510	                           " BATCH_SIZE");
511	        if (argc == 4 && std::strcmp(argv[1], "build") == 0) {
512	            std::vector<Prefix> fx = parse_fib(argv[2]);
513	            const std::vector<Row> rows = compile_rows(fx);
514	            write_image(argv[3], serialize_image(rows));
515	            return 0;
516	        }
517	        if (std::strcmp(argv[1], "lookup") == 0 && argc >= 5) {
518	            if (argc == 5 && std::strcmp(argv[4], "scalar") == 0) {
519	                const std::vector<Row> rows = load_image(argv[2]);
520	                const std::vector<std::uint64_t> keys = parse_trace(argv[3]);
521	                emit_answers(rows, keys, 1);
522	                return 0;
523	            }
